def closures(evts, ws, we, delta=800):
    # supporting edges: any events; closing edge must be in window
    res=[]
    # build adjacency list of (neighbor, time) sorted
    adj=collections.defaultdict(list)
    for u,v,t in evts:
        adj[u].append((t,v)); adj[v].append((t,u))
    for k in adj: adj[k].sort()
    for u,v,t in evts:
        if not (ws<=t<=we): continue
        # find common contacts c with edges u-c at t1<=t and v-c at t2<=t, max(t1,t2)>=t-delta
        cu={}
        for t1,c in adj[u]:
            if t1<t: cu[c]=t1  # latest before t
        best=None
        for t2,c in adj[v]:
            if t2<t and c in cu and c!=u and c!=v:
                m=max(t2,cu[c])
                if t-m<=delta:
                    res.append((u,v,t,c,cu[c],t2))
    return res
