import collections
def closures_count(evts, ws, we, delta=800):
    adj=collections.defaultdict(list)
    for u,v,t in evts:
        adj[u].append((t,v)); adj[v].append((t,u))
    for k in adj: adj[k].sort()
    n=0
    for u,v,t in evts:
        if not (ws<=t<=we): continue
        cu={}
        for t1,c in adj[u]:
            if t1<t: cu[c]=t1
        for t2,c in adj[v]:
            if t2<t and c in cu and c!=u and c!=v and t-max(t2,cu[c])<=delta:
                n+=1
    return n
